import { describe, expect, it } from "vitest";
import { mergeUsagePricingBucket } from "../src/lib/usage-pricing-context.js";
import { priceRollup } from "../src/lib/llm-pricing.js";

// Request-level pricing bucket regression: the same aggregate token total
// must be priced per-request contract (cache read, long-context threshold,
// service tier, regional processing) instead of being averaged or summed into
// a single legacy rate. We build buckets with mergeUsagePricingBucket and price
// them through priceRollup, which prices each bucket independently.

// Build a priceable aggregate row by merging the given per-request usages.
function pricedRow(usages) {
  const entry = { provider: "openai", model: "gpt-6-sol" };
  for (const usage of usages) mergeUsagePricingBucket(entry, usage);
  const totals = usages.reduce(
    (acc, u) => {
      acc.input += u.inputTokens ?? 0;
      acc.output += u.outputTokens ?? 0;
      return acc;
    },
    { input: 0, output: 0 },
  );
  entry.inputTokens = totals.input;
  entry.outputTokens = totals.output;
  entry.totalTokens = totals.input + totals.output;
  return entry;
}

const rollCost = (entry) => priceRollup({ byModel: [entry] }).cost.totalCost;

describe("verify-04 request-level pricing buckets", () => {
  it("prices cache-read tokens at the cache contract, not as uncached input", () => {
    // Same total tokens (101000), same model/tier/region; only the cache split
    // differs between the positive (cached) and negative (all-uncached) rows.
    const cached = pricedRow([
      { inputTokens: 60000, cacheReadTokens: 40000, outputTokens: 1000 },
    ]);
    const uncached = pricedRow([
      { inputTokens: 100000, outputTokens: 1000 },
    ]);
    expect(uncached.totalTokens).toBe(cached.totalTokens);
    expect(cached.pricingBuckets).toHaveLength(1);
    // uncached: 100000*2/M + 1000*10/M = 0.21
    expect(rollCost(uncached)).toBeCloseTo(0.21, 9);
    // cached: 60000*2/M + 40000*2*0.1/M + 1000*10/M = 0.138
    expect(rollCost(cached)).toBeCloseTo(0.138, 9);
    expect(rollCost(cached)).not.toBeCloseTo(rollCost(uncached), 9);
  });

  it("keeps long-context and short requests in separate priced buckets", () => {
    // Same total tokens (301000 total = 300000 input + 1000 output).
    const mixed = pricedRow([
      { inputTokens: 272001, outputTokens: 500 },
      { inputTokens: 27999, outputTokens: 500 },
    ]);
    const allShort = pricedRow([
      { inputTokens: 150000, outputTokens: 500 },
      { inputTokens: 150000, outputTokens: 500 },
    ]);
    expect(mixed.totalTokens).toBe(allShort.totalTokens);
    expect(mixed.pricingBuckets).toHaveLength(2);
    expect(allShort.pricingBuckets).toHaveLength(1);
    // allShort: 300000*2/M + 1000*10/M = 0.61
    expect(rollCost(allShort)).toBeCloseTo(0.61, 9);
    // mixed long(272001,500)=1.088004+0.0075 + short(27999,500)=0.055998+0.005
    expect(rollCost(mixed)).toBeCloseTo(1.156502, 6);
    expect(rollCost(mixed)).not.toBeCloseTo(rollCost(allShort), 9);
  });

  it("segregates service tiers so tier multipliers price per request", () => {
    const mixedTier = pricedRow([
      { inputTokens: 1000, outputTokens: 100, service_tier: "standard" },
      { inputTokens: 1000, outputTokens: 100, service_tier: "fast" },
    ]);
    const allStandard = pricedRow([
      { inputTokens: 1000, outputTokens: 100, service_tier: "standard" },
      { inputTokens: 1000, outputTokens: 100, service_tier: "standard" },
    ]);
    expect(mixedTier.pricingBuckets).toHaveLength(2);
    expect(allStandard.pricingBuckets).toHaveLength(1);
    // standard 0.003; fast (multiplier 2) 0.006; mixed total 0.009
    expect(rollCost(allStandard)).toBeCloseTo(0.006, 9);
    expect(rollCost(mixedTier)).toBeCloseTo(0.009, 9);
    expect(rollCost(mixedTier)).not.toBeCloseTo(rollCost(allStandard), 9);
  });

  it("segregates regional processing as a separate per-request bucket", () => {
    const mixedRegion = pricedRow([
      { inputTokens: 1000, outputTokens: 100, regional_processing: false },
      { inputTokens: 1000, outputTokens: 100, regional_processing: true },
    ]);
    const allLocal = pricedRow([
      { inputTokens: 1000, outputTokens: 100, regional_processing: false },
      { inputTokens: 1000, outputTokens: 100, regional_processing: false },
    ]);
    expect(mixedRegion.pricingBuckets).toHaveLength(2);
    expect(allLocal.pricingBuckets).toHaveLength(1);
    // local 0.003 each -> 0.006; regional adds 1.1 multiplier on one request
    expect(rollCost(allLocal)).toBeCloseTo(0.006, 9);
    expect(rollCost(mixedRegion)).toBeCloseTo(0.0093, 9);
    expect(rollCost(mixedRegion)).not.toBeCloseTo(rollCost(allLocal), 9);
  });
});

import { describe, expect, it } from "vitest";
import { mergeUsagePricingBucket } from "../src/lib/usage-pricing-context.js";
import { priceRollup } from "../src/lib/llm-pricing.js";

// Acceptance: same grand-total tokens but different per-request cache / long
// context distributions must be billed per-request (never on a merged sum).
// mergeUsagePricingBucket splits requests into pricingBuckets keyed by the
// long-context flag; priceRollup prices each bucket with that request's
// multipliers.

const OPENAI_MODEL = "gpt-6-sol"; // documented openai model with pricing terms

const buildModel = () => ({
  provider: "openai",
  model: OPENAI_MODEL,
  inputTokens: 0,
  outputTokens: 0,
  cacheReadTokens: 0,
  cacheCreationTokens: 0,
  totalTokens: 0,
  calls: 0,
});

/** Merge one request at a time, then price the aggregate via priceRollup. */
const priced = (records) =>
  priceRollup({
    byModel: [
      records.reduce((entry, u) => {
        mergeUsagePricingBucket(entry, u);
        return entry;
      }, buildModel()),
    ],
  });

describe("request-level pricing cache & long-context distribution", () => {
  it("splits an equal-total set across the long-context boundary per request", () => {
    // Both aggregates total 600000 prompt tokens, but distribution differs.
    const allLong = [300000, 300000]; // each > 272000 -> all long (2x input)
    const splitLongShort = [400000, 200000]; // one long, one short (1x)
    const byModel = [400000, 200000].reduce((entry, input) => {
      mergeUsagePricingBucket(entry, { inputTokens: input });
      return entry;
    }, buildModel());
    const allLongCost = priced(allLong.map((inputTokens) => ({ inputTokens })));
    const splitCost = priced(splitLongShort.map((inputTokens) => ({ inputTokens })));
    expect(allLongCost).toBeGreaterThan(splitCost);
    // Splitting produces distinct short vs long buckets; all-long stays one.
    expect(byModel.pricingBuckets).toHaveLength(2);
    expect(priced(allLong.map((inputTokens) => ({ inputTokens })))).toBe(allLongCost);
  });

  it("does not change cost when equal totals move within the same long flag", () => {
    // Same total 600000, both requests stay long (>272000): only the long flag
    // (not arbitrary distribution) must drive pricing, so cost is unchanged.
    const a = priced([300000, 300000].map((inputTokens) => ({ inputTokens })));
    const b = priced([301000, 299000].map((inputTokens) => ({ inputTokens })));
    expect(a).toBeCloseTo(b, 10);
    expect(a).toBeGreaterThan(0);
  });

  it("prices cache reads at the discounted rate for equal prompt totals", () => {
    // Equal grand totals (600000) and both requests long; only cacheRead
    // composition differs. Cached tokens bill at 0.1x of the input rate.
    const fresh = priced([{ inputTokens: 300000 }, { inputTokens: 300000 }]);
    const cached = priced([
      { inputTokens: 200000, cacheReadTokens: 100000 },
      { inputTokens: 300000 },
    ]);
    expect(cached).toBeLessThan(fresh);
    expect(cached).toBeGreaterThan(0);
  });

  it("prices equal cache composition identically regardless of which request carries it", () => {
    // Swap which request holds the cached tokens: same totals, same cache
    // counts, so cost must be equal (identity/order is not the differing input).
    const first = priced([
      { inputTokens: 200000, cacheReadTokens: 100000 },
      { inputTokens: 300000 },
    ]);
    const second = priced([
      { inputTokens: 300000 },
      { inputTokens: 200000, cacheReadTokens: 100000 },
    ]);
    expect(first).toBeCloseTo(second, 10);
    expect(first).toBeGreaterThan(0);
  });

  it("treats 272000 as short and the first larger request as long", () => {
    // Accepted boundary (threshold itself is NOT long) and first rejected value.
    const entry = buildModel();
    mergeUsagePricingBucket(entry, { inputTokens: 272000 });
    mergeUsagePricingBucket(entry, { inputTokens: 272001 });
    expect(entry.pricingBuckets).toHaveLength(2);
    const byRequest = new Map(
      entry.pricingBuckets.map((b) => [b.requestInputTokens, b.longFlag]),
    );
    expect(byRequest.has(272000)).toBe(true);
    expect(byRequest.has(272001)).toBe(true);
    // 272000 is the short bucket; 272001 is the long bucket.
    const short = entry.pricingBuckets.find((b) => b.requestInputTokens === 272000);
    const long = entry.pricingBuckets.find((b) => b.requestInputTokens === 272001);
    expect(short.requestInputTokens > 272000).toBe(false);
    expect(long.requestInputTokens > 272000).toBe(true);
    // The two buckets must price differently at the request boundary.
    expect(priceRollup({ byModel: [{ ...entry }] }).cost.totalCost).toBeGreaterThan(
      0,
    );
  });

  it("rejects a negative token count in a pricing bucket", () => {
    const entry = buildModel();
    expect(() =>
      mergeUsagePricingBucket(entry, { inputTokens: 100, cacheReadTokens: -5 }),
    ).toThrow(TypeError);
  });
});

