// Request-level pricing bucket regression: the same aggregate token total
// must be priced per-request contract (cache read, long-context threshold,
// service tier, regional processing) instead of being averaged or summed into
// a single legacy rate. We build buckets with mergeUsagePricingBucket and price
// them through priceRollup, which prices each bucket independently.

// Build a priceable aggregate row by merging the given per-request usages.
function pricedRow(usages) {
  const entry = { provider: "openai", model: "gpt-6-sol" };
  for (const usage of usages) mergeUsagePricingBucket(entry, usage);
  const totals = usages.reduce(
    (acc, u) => {
      acc.input += u.inputTokens ?? 0;
      acc.output += u.outputTokens ?? 0;
      return acc;
    },
    { input: 0, output: 0 },
  );
  entry.inputTokens = totals.input;
  entry.outputTokens = totals.output;
  entry.totalTokens = totals.input + totals.output;
  return entry;
}

